from book import Chapter
c=Chapter('12')
c.src('R54800',0,start='这样的话，实际上把整个用户',end='这样一个虚拟机。',replacements=[('这样的话，实际上把整个用户的自己的数字空间中所能用到的数据和代码全都用语义空间，在语义空间里面建立起一个巨大的 Morco DAG 的树','可以把用户数字空间中能够使用的数据和代码，放进一个由语义关系组织的 Merkle-DAG'),('然后用它来描述这个用户，每一个用户自己所能够访问的数字空间的功能和数据','用它描述每个用户能够访问的功能和数据'),('然后就是把代码和数据整个用这个搭起一个虚拟机','在这些代码和数据的基础上，构造一个个人虚拟机'),('这个所有的功能和数据的这样一个虚拟机','全部功能和数据组成的虚拟机')])
c.add('''这个虚拟机的中心，是个人能够使用什么、希望完成什么。物理设备仍然存在，但用户不必在每次表达需求时，先替系统完成资源分配。手机、桌面电脑、家庭存储和云端资源，可以成为同一个个人空间的不同组成部分。

这使“我的电脑”获得了一种新的含义：它不只是一台放在桌上的机器，也可以是围绕本人组织的一组数据、能力和受控资源。''')
c.heading('一台手机，怎样使用分散在其他地方的能力')
c.src('R54800',0,start='有了这虚拟机呢',end='但实际上运行体系是在整个数字空间当中自动完成的。',replacements=[('有了这虚拟机呢，它就实际上这跟用户手里的任何一台手机、电脑、平板不一样，它是一个虚拟的。有了它之后，我想是不是能完成这样一个功能，就用户直接在这个虚拟机上操作','有了这个虚拟空间之后，用户可以直接在其中表达任务'),('他不用担心底层究竟我该具体使用哪台设备，这个应用我发布的命令是应用在哪台具体的设备上。我要访问的数据在哪台具体的物理设备上','不必每次先考虑具体使用哪台设备、命令在哪台设备上运行、数据保存在哪台设备上'),('我现在拿的实际上是这台手机，但是呢，我这台手机上运行着这个虚拟机。然后比如我要下命令','我现在拿着手机，通过它使用这个空间。比如我提出任务'),('我要用 BT 软件下载一个非常大的视频文件。这种情况基本上是不可……一般用户是不会在手机上来下','下载一份可以合法取得的大型视频资料。如果手机空间有限，就不适合让全部工作都留在手机上'),('因为手机空间比较小。然后呢，长期后台运行 BT 软件能耗比较大，一般都是在台式机上来完成的','长期后台下载还会占用电量，更适合交给能够持续运行的设备'),('但用户完全不必担心这','用户可以提出需求和约束'),('就会自动地','可以在授权范围内'),('就是说将来呢，这台虚拟机，每一台，就是你手里的每一个物理的设备，都是在上它运行的这个虚拟软件','就是说，每一台物理设备上运行的入口'),('有的时候也是我要访问某一个文件','\n\n访问一个文件时也一样'),('比如如果在本地','如果在本地')])
c.add('''这种调度需要知道设备是否在线、剩余空间、网络条件、耗电与允许承担的任务。如果家庭电脑关机了，系统应当能够说明这一点，或者在已有授权范围内选择其他路径。对用户隐藏不必要的复杂性，不等于假装限制不存在。

数据也需要有清楚的版本。手机上看到的是哪一份内容，远端处理用了哪一版，结果回到哪里，这些关系都可以被记录。这样，个人空间跨越设备以后，仍然能够保持可理解、可检查。''')
c.heading('从个人空间到共同网络，哪些内容可以共享')
c.src('R54800',0,start='而且如果这个机制将来运行好了之后',end='把它储存到全球的巨大的云空间当中。',replacements=[('而且如果这个机制将来运行好了之后，就每一个用户都有自己的这样一个 Morco DAG 的一个树，是这样的结构的一个虚拟机','如果这个机制逐步形成，每个用户都可以拥有按 Merkle-DAG 组织的个人空间'),('实际上这所有的这些代码和数据所形成的这些数字空间，每一个人的独自的那个数字空间当中的什么，其实有很多都是重复的','这些个人空间中的代码与数据，有一部分其实是重复的'),('比如很多公共资源，你要看的肖申克救赎跟另外一个电脑上要看的，实际上可能是同一个视频文件','比如公开发布的资料、同一版本的开源程序，可能被许多人共同使用'),('实际上就是相当于就跟现在云存储一样，实际上它为每一个用户存储的数据当中有很大一部分实际上都是通过类似于这个哈希去重之后，它只保留一个备份，只保留一个数字的那个版本','对于可以共享的相同内容，可以通过内容身份识别重复，避免每个个人空间都保存互不相关的逻辑副本；实际可靠性仍需要多个物理副本'),('然后呢，就是现在好多提供云存储都是每人提供多少TB空间，实际上总的那个存储空间并不是所有用户的这个存储空间加在一起，因为有很多都是重复的','因此，个人可见的资源集合与底层实际占用空间，不必简单相加'),('Morco Tree','Merkle 图'),('Morco DAG Tree','Merkle-DAG'),('然后把这些数据和代码在全球通过类似于那内容分发网络一样，做好拓扑的设置，然后呢把它储存到全球的巨大的云空间当中','对适合共享的内容，可以按访问需要与可靠性要求安排存储和分发')])
c.add('''共享内容并不要求共享所有人的私人资料。一份公开程序可以被许多人引用，各自的日记、账户和授权则属于不同边界。底层内容相同，也不意味着一个用户自动获得另一个用户的权限。

同样，个人空间能够迁移，不等于任意陌生终端都值得信任。数据在传输和保存时加密，不能消除正在使用的设备截取输入或屏幕的风险。这个框架要增加的是选择设备和服务的能力，同时让每次访问的条件能够被理解。''')
c.heading('种子怎样先利用旧系统，再逐步改造它')
c.src('R55647',1,replacements=[('我在想，是不是可以用这样一种机制','我设想这样一种机制'),('这个种子的投放','一个软件种子的部署'),('投放到','部署到'),('通过自我发育自我成长','通过持续分析、构造与反馈'),('使他','使它'),('没有任何不同','可以按共同接口被识别和使用'),('一方面为旧生态对象生成一层merkle包装','先为旧生态对象生成一层 Merkle 包装'),('然后这个包裹着旧生态对象的种子，一方面','\n\n然后，这个包裹旧生态对象的种子，一方面'),('种子投放包裹','部署与包装')])
c.add('''“包装”在这里有具体含义：明确原系统提供什么功能、接收什么输入、产生什么输出，以及依赖哪些环境。最初可以继续调用原来的软件，让用户马上得到用途；随后再分析其中哪些部分值得拆开，哪些重复工作可以形成热路径，哪些接口可以被更清楚的结构替代。

这使旧系统成为可以进入新框架的材料。迁移不必等到一切都重写完成才开始，也不必一次拆掉正在使用的全部工具。每次替换，都应当说明外部约定是否仍然满足，哪些行为改变了，怎样在需要时返回原来路径。''')
c.src('R49187',0,start='我之前说的也可以实现原本属于计算机语言核心和标准库的微观功能',end='速度更快了的感受。',replacements=[('我之前说的也可以实现原本属于计算机语言核心和标准库的微观功能','对于原本属于计算机语言核心与标准库的微观功能'),('因为如果这个merkle-DAG语义框架本身对语义的天然封装性，这种内核的替换，不会影响到其他任何上层模块','若语义约定与实现的边界清楚，内核替换就有机会减少对上层模块的影响'),('会是很平滑很无痛无感的过程','就有条件把迁移的影响控制在清楚的范围内')])
c.heading('让 AI 能够工作，也让个人保有控制')
c.src('R48769',0,end='来完成想做的任务，',replacements=[('如果我想做一个','可以设想一个'),('同时其运行环境不会影响外部操作系统','使其活动首先限定在明确的运行环境内'),('它可以与访问宿主机资源','它可以访问获准使用的宿主机资源'),('但是必须通过宿主机批准，这个但是AI虚拟主机上的','但需要宿主机一侧授权；AI 虚拟主机内的'),('都有AI自己掌控','可以在预先给定的范围内由 AI 执行'),('来完成想做的任务，','来完成想做的任务。')])
c.src('R48769',0,start='或者在不具备任何计算机专业知识和技能的情况下',end='虚拟机上的AI Agent自动帮助用户完成任务。',replacements=[('或者在不具备任何计算机专业知识和技能的情况下','不具备相应专业知识的用户，也可以')])
c.add('''这里的目标，是把经常重复的细碎操作放进明确范围，使用户不必对每一个内部步骤重新作决定；同时，范围之外的现实影响不能因为 AI 已经在内部成功运行，就自动获得权限。

一个脚本可以在自己的资料副本上自由试验，与它能够修改用户唯一的原始文件，是不同的安排。一个服务能够提出购买硬件的建议，与它能够花费共同资金，也不是同一件事。个人控制需要体现在这些实际作用发生的地方。''')
c.heading('自举：让构造工具逐渐参与自己的成长')
c.src('R49234',0,start='而我的尝试，则是从一个尚未完全进化成AGI的原始鸡(LLM)开始',end='你觉得这个想法可行吗？',replacements=[('而我的尝试，则是','我的尝试，是'),('这个项目','这个构造框架'),('它们的奖励函数肯定是多元的','它们的评价条件往往是多元的'),('但是我的项目所遵循的第一性原理中的那个最根本的奖励函数也是唯一的','而这些具体评价，可以继续追问它们与共同构造原则的关系'),('你说的第三个，持续学习的问题，其实就是这个不动点的自我指向的态射/路径在运行时的动态特征','持续学习的问题，则需要在运行中的反馈与修正里展开'),('最终构建一个Oak版的AI模型','逐步构造具有更强持续学习与自主构造能力的模型'),('具备完备AGI DNA的蛋','能够继续成长的智能种子'),('你觉得这个想法可行吗？','这个方向需要靠实际的自举过程一步步推进。')])
c.add('''鸡与蛋的类比表达了两条起点不同的路径：可以先设想一个最简机制怎样长出复杂智能，也可以先利用已经存在的智能，构造更好的表示、工具和学习过程。我的实践选择后一个入口，让现有 AI 与人共同工作，逐渐形成能够帮助自身改进的能力。

自举也不意味着所有改动都立即替换正在运行的系统。新方法可以先在副本和明确任务中接受检验，证明有用以后再进入下一轮。能够保存旧版本、理解改变原因、失败时返回可用状态，正是这种成长得以持续的条件。

由此，MerkleVM 的远景既是个人数字空间，也是共同构造网络中的一个入口。它从现有设备、现有应用和真实需求开始，逐步把分散能力组织起来。要让这种成长不依赖一人不断手工搬运讨论，研究与开发本身也需要新的合作方式。''')
c.save({'reasoning':'以个人为中心的虚拟空间→跨设备任务→公共与私有内容→包装旧生态→渐进替换→授权边界→自举','examples':['手机发起远端下载','文件跨本地局域网云访问','公共程序内容共享','逐层包装电脑应用任务','资料副本试验','鸡生蛋与蛋生鸡'],'objections':['虚拟空间忽视物理约束吗','内容去重等于权限共享吗','任何电脑登录都安全吗','自举是否自行扩大权限'],'voice':'长段保留作者口述设备愿景、软件种子与沙箱方案；清理口述重复并修正无条件安全和当前实现断言','status':'初校；愿景与已部署能力不混写'})
